EnemyLibrary.sample=function(o,i,age){const offset=o.formationOffsets?.[i];let x=o.x+(offset?.x??(i-(o.count-1)/2)*o.gap),y=o.y+(offset?.y??0),z=o.depth+(offset?.z??i*100)-age*o.speed,phase=age*1.4+i*.785398;switch(o.mode){case 7:y+=Math.abs(x)*.22;x+=120*Math.sin(age*.7);break;case 8:y+=i*100-130;x-=age*35;break;case 9:y=1200+i*80-age*140;x+=100*Math.sin(age);break;case 10:x+=450*Math.sin(age*.8);y+=100*Math.cos(age*.8);break;case 11:x+=170*Math.sin(age*2+i);break;case 12:x+=(x>=0?1:-1)*age*110;y+=age*15;break;case 13:x*=.8;y+=i%2?90:-90;break;case 14:x+=180*Math.cos(phase);y+=200*Math.sin(phase);break;case 15:y=130+50*Math.sin(age+i);x+=120*Math.cos(age);break;case 16:x+=(i%2?1:-1)*900*Math.exp(-age*.4);break;case 17:y+=i%2?160:-110;break;case 18:x+=age*(i-3)*35;y-=age*20;break;case 19:y+=190*Math.sin(age*.9+i);break;case 20:x+=200*Math.sin(age+i*.65);y+=80*Math.cos(age+i);break;case 21:y+=i*90;x+=age*30;break;case 22:x+=250*Math.sin(age*1.3+(i%2)*Math.PI);y+=i%2?100:-70;break;case 23:x*=.65+.35*Math.cos(age*.6);y+=i%2?170:-90;break;case 24:x+=130*Math.cos(phase);y+=180*Math.sin(phase);break;case 25:y+=Math.abs(x)*.3;x*=.9;break;case 26:x+=240*Math.sin(age*.55);y+=120*Math.sin(age*1.1+i);break;case 27:x+=age*(i-1)*50;y+=70*Math.cos(age);break;case 28:y+=i*150+100*Math.sin(age*.7);x+=80*Math.cos(age);break;case 29:y=950-age*100+i*100;x+=age*(i-1)*55}return [x,y,z]};

